mapper.select:
SELECT  FROM TB_PAY_OUT

    AND SRC_TYPE = #{srcType}
    AND SRC_NO = #{srcNo}
    AND CONTRACT_NO = #{contractNo}
    AND STAT_CD = #{statCd}

 ORDER BY PAYOUT_ID DESC
 LIMIT #{limit}

mapper.update:
UPDATE TB_PAY_OUT
   SET STAT_CD = #{statCd}, RESULT_CD = #{resultCd}, RESULT_MSG = #{resultMsg}, SEND_COUNT = #{sendCount},
       INQUIRY_COUNT = COALESCE(#{inquiryCount, jdbcType=INTEGER}, INQUIRY_COUNT), NEXT_TRY_DT = #{nextTryDt}
       , SENT_DT = COALESCE(SENT_DT, #{now})
       , DONE_DT = #{now}
 WHERE PAYOUT_ID = #{payoutId}
